import {createCatchWorld} from './catch-world.js';
import {createCatchGame,startCatchGame,pressCatchKey,tickCatchGame,setCatchPaused,snapshotCatch,restoreCatch,migrateAdventureCatch,getCatchTarget,MAIN_CATCH_STORAGE_KEY} from './catch-game.js';
import {createFeedback,isControlActivation} from './feedback.js';
import {LEVELS,getLevel,getFinger} from './curriculum.js';
import {loadProgress,saveProgress,snapshotAdventure,recordCompletion,getAccuracy,validateProgress,STORAGE_KEY} from './adventure.js';
const $=id=>document.getElementById(id),label=k=>k==='Space'?'空格':k==='Backspace'?'退格':k??'';
let storage;try{storage=localStorage;}catch{}
const loaded=loadProgress(storage);let progress=loaded.progress,persistent=loaded.persistent,conflict=false;
const requested=Number(new URL(location.href).searchParams.get('level')||1),level=getLevel(requested)||LEVELS[0];
let sessions={},journeys={},state,world,raf,previous=performance.now(),lastSave=0;
try{const raw=JSON.parse(storage?.getItem(MAIN_CATCH_STORAGE_KEY)||'null');if(raw?.version===2&&raw.sessions&&typeof raw.sessions==='object'){if(validateProgress(raw.progress))progress=raw.progress;if(raw.journeys&&typeof raw.journeys==='object')journeys=raw.journeys;for(const [id,snap]of Object.entries(raw.sessions)){const restored=restoreCatch(snap);if(restored&&String(restored.levelId)===id)sessions[id]=snap;}}}catch{}
// Migrate the previous mainline attempt before any new selection can replace active.
if(progress.active&&!sessions[progress.active.levelId]){const migrated=migrateAdventureCatch(progress);if(migrated){if(migrated.phase==='complete')recordCompletion(progress,migrated);sessions[migrated.levelId]=snapshotCatch(migrated);}}
state=restoreCatch(sessions[level.id]);
state??=createCatchGame(level.id,progress);
if(!['ready','complete'].includes(state.phase))setCatchPaused(state,true);
try{world=createCatchWorld($('catchWorld'));world.setCompleted?.(Object.keys(progress.completed).map(Number));}catch(error){console.error(error);$('catchError').hidden=false;}
$('lessonTitle').textContent=`${level.id}. ${level.title}`;document.title=`第${level.id}关 ${level.title} · 敲敲岛`;
const feedback=createFeedback(value=>{$('catchFeedback').classList.toggle('visible',!!value);for(const el of document.querySelectorAll('[data-key]'))el.classList.toggle('wrong',value?.pressed===el.dataset.key);if(value){$('actualKey').textContent=label(value.pressed);$('feedbackText').textContent=`按到了 ${label(value.pressed)}，试试${getFinger(value.target)?.label??''} ${label(value.target)}`;}});
function save(){if(conflict)return;if(state.phase!=='complete')progress.active=snapshotAdventure(state);try{if(!storage)throw Error();sessions[level.id]=snapshotCatch(state);storage.setItem(MAIN_CATCH_STORAGE_KEY,JSON.stringify({version:2,sessions,journeys,lastJourney:null,progress}));persistent=true;saveProgress(storage,progress);}catch{persistent=false;}$('catchSave').textContent=persistent?'进度保存在本机 · 实体键盘 · 英文输入法':'暂时无法保存，请保持页面打开 · 实体键盘练习';}
function announce(){const t=getCatchTarget(state);$('catchAnnouncement').textContent=state.target?`果子 ${t.fruitLabel}，下一个键 ${label(state.target)}，${getFinger(state.target)?.label??''}`:'本关完成，可以重玩或回地图自由选关';}
function render(){const done=state.phase==='complete',ready=state.phase==='ready',t=getCatchTarget(state),finger=getFinger(state.target);$('fruitCount').textContent=t.fruitIndex;$('fruitTotal').textContent=t.fruitTotal;$('startCatch').hidden=!ready;$('pauseCatch').hidden=ready||done;$('catchDone').hidden=!done;$('catchPause').hidden=!state.paused||done||ready;document.querySelector('.catch-game').classList.toggle('complete-mode',done);
$('keyHints').replaceChildren();const keys=[...new Set([...(level.newKeys.length?level.newKeys:['F','J']),...(state.target?[state.target]:[])])];for(const k of keys){const el=document.createElement('span');el.className='key'+(k===state.target?' active':'');el.dataset.key=k;el.textContent=label(k);if(k.length>1)el.classList.add('wide');$('keyHints').append(el);}
$('fingerCue').textContent=done?'练习完成，手指放松一下':`${finger?.label??'手指'}按 ${label(state.target)}`;
$('returnCue').textContent=finger?.returnHint??'手腕放松，眼睛看果子';
$('typedLine').hidden=level.id<10||state.index<state.reviewCount;$('typedBuffer').textContent=state.buffer||'…';
let title,text;if(done){title='收获满满，谢谢你';text='每一次认真练习都算数';}else if(ready){title='准备好，再出发';text=state.index<state.reviewCount?'先复习以前容易按错的字母，再开始本关新任务':level.subtitle;}else if(state.phase==='catching'){title='接住啦！';text='小熊把这份收获放进篮子';}else if(t.kind==='backspace'){title='擦掉多出来的字母';text='catt 多了一个 t，用右手小指按退格，变成 cat';}else if(t.kind==='space'){title='让两个词分开';text='用拇指轻按空格，为下一个词留出位置';}else if(state.phase==='intro'){title='先认识这个键';text=`果子先不动，用${finger?.label??''}找到 ${label(state.target)}`;}else if(state.phase==='waiting'){title='果子在草地上等你';text=t.kind==='word'?'按顺序完成这个词，果子不会消失':`慢慢找，用${finger?.label??''}按 ${label(state.target)}`;}else{title=state.index<state.reviewCount?'先复习一下':'慢慢来';text=t.kind==='word'?'字母会依次亮起，完成整个词，小熊再接住它':'没接住也没关系，果子会落地等你';}
$('gentleTitle').textContent=title;$('gentleText').textContent=text;$('sceneInstruction').textContent=done?level.reward.description:state.phase==='catching'?'小熊正在收好你的字母果子':level.id>=10?'看果子上的词，依次按字母；亮起后，小熊接住它':'看果子上的字母，按键让小熊接住它';
$('doneHeading').textContent=`第 ${level.id} 关完成啦！`;$('doneText').textContent=`${level.reward.icon} ${level.reward.name}已留在小岛 · 本轮准确率 ${Math.round(getAccuracy(state)*100)}%`;$('accuracyTip').textContent=getAccuracy(state)<.9?'可以再练一次，也可以回地图探索别的关卡':'做得好，休息一下，再选喜欢的关卡';}
function start(){if(!world||conflict)return;feedback.clear();startCatchGame(state);render();announce();save();$('startCatch').blur();}
function pause(){if(!world||state.paused||['ready','complete'].includes(state.phase))return;feedback.clear();setCatchPaused(state,true);render();save();$('resumeCatch').focus({preventScroll:true});}
function resume(){if(conflict)return;feedback.clear();setCatchPaused(state,false);render();announce();save();$('resumeCatch').blur();}
$('startCatch').onclick=start;$('pauseCatch').onclick=pause;$('resumeCatch').onclick=resume;$('replayCatch').onclick=()=>{feedback.clear();state=createCatchGame(level.id,progress);render();save();$('startCatch').focus({preventScroll:true});};
window.addEventListener('keydown',e=>{const modal=!$('catchPause').hidden?$('catchPause'):!$('catchDone').hidden?$('catchDone'):null;if(modal){if(e.key==='Tab'){const all=[...modal.querySelectorAll('button,a')],first=all[0],last=all.at(-1);if(!all.includes(document.activeElement)||(!e.shiftKey&&document.activeElement===last)){e.preventDefault();first.focus();}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}}return;}
if(!world||conflict||e.ctrlKey||e.altKey||e.metaKey||e.shiftKey||e.repeat)return;if(e.isComposing||e.keyCode===229||e.which===229){$('sceneInstruction').textContent='请切换到英文输入法，再按果子上的字母';return;}if(e.key==='Escape'){pause();return;}if(isControlActivation(e,document.activeElement))return;if(state.phase==='ready'&&e.key==='Enter'){e.preventDefault();start();return;}const result=pressCatchKey(state,e);if(result.kind==='wrong'){e.preventDefault();feedback.wrong(result.pressed??e.key,state.target);save();}else if(result.kind==='correct'||result.kind==='letter'){e.preventDefault();feedback.clear();render();announce();save();}});
window.addEventListener('storage',e=>{if(e.storageArea!==storage||![STORAGE_KEY,MAIN_CATCH_STORAGE_KEY,null].includes(e.key))return;conflict=true;feedback.clear();setCatchPaused(state,true);render();$('catchDone').hidden=true;$('catchPause').hidden=false;$('pauseHeading').textContent='另一页面更新了学习记录';$('catchPause').querySelector('p').textContent='为避免覆盖新记录，请刷新后继续';$('resumeCatch').textContent='刷新并继续';$('resumeCatch').onclick=()=>location.reload();$('resumeCatch').focus();});
window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('pagehide',()=>{save();feedback.clear();cancelAnimationFrame(raf);world?.dispose();});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
function frame(now){const dt=Math.max(0,(now-previous)/1000);previous=now;const changed=tickCatchGame(state,dt);if(changed){if(state.phase==='complete'){recordCompletion(progress,state);world?.setCompleted?.(Object.keys(progress.completed).map(Number));}render();announce();save();if(state.phase==='complete')$('replayCatch').focus({preventScroll:true});}world?.render(state,dt);if(now-lastSave>1500&&!state.paused&&!['ready','complete'].includes(state.phase)){save();lastSave=now;}raf=requestAnimationFrame(frame);}
render();save();if(state.paused)$('resumeCatch').focus();else if(state.phase==='complete')$('replayCatch').focus();else $('startCatch').focus();raf=requestAnimationFrame(frame);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
